import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { getTowerTierStats, TOWER_DEFS, TOWER_TYPES } from '../../src/data/towers.ts';
import l1cJson from '../../src/data/levels2d/l1c.json';

/**
 * The L1c plots are generated by tools/map-compose/compose.py (see its header for the rules); this
 * re-checks the rules on the shipped data against the SIM polylines (what enemies walk), so a
 * hand edit of l1c.json or a re-generation cannot quietly break them.
 */
const ROOT = resolve(import.meta.dirname, '../..');
const L = l1cJson as { imageSize: number[]; safeArea: number[]; plots: number[][]; paths: number[][][]; entrances: { x: number; y: number }[]; goal: number[]; plotRadiusPx?: number; pxPerUnit?: number };
const [IW, IH] = L.imageSize;
const PPU = L.pxPerUnit ?? 50;
const R = L.plotRadiusPx ?? 48;
const RY = (R * 343) / 512; // plot-base.png aspect
const ROAD_HALF = (0.068 * IH) / 2;
const plots = L.plots.map(([x, y]) => ({ x, y }));

function segDist(px: number, py: number, a: number[], b: number[]): number {
  const vx = b[0] - a[0];
  const vy = b[1] - a[1];
  const t = Math.max(0, Math.min(1, ((px - a[0]) * vx + (py - a[1]) * vy) / (vx * vx + vy * vy || 1)));
  return Math.hypot(a[0] + vx * t - px, a[1] + vy * t - py);
}

function roadDist(x: number, y: number): number {
  let best = Infinity;
  for (const path of L.paths) for (let i = 0; i < path.length - 1; i++) best = Math.min(best, segDist(x, y, path[i], path[i + 1]));
  return best;
}

function samples(step: number): number[][] {
  const out: number[][] = [];
  for (const path of L.paths) {
    for (let i = 0; i < path.length - 1; i++) {
      const [ax, ay] = path[i];
      const [bx, by] = path[i + 1];
      const n = Math.max(1, Math.ceil(Math.hypot(bx - ax, by - ay) / step));
      for (let k = 0; k <= n; k++) out.push([ax + ((bx - ax) * k) / n, ay + ((by - ay) * k) / n]);
    }
  }
  return out;
}

describe('L1c plots (generated layout)', () => {
  it('has 24 plots and they match the generator output', () => {
    expect(plots).toHaveLength(24);
    const gen = JSON.parse(readFileSync(resolve(ROOT, 'tools/map-compose/l1c.plots.json'), 'utf8')) as number[][];
    expect(gen).toEqual(L.plots);
  });

  it('every plot (and the tallest tower on it) is inside the safe area', () => {
    const [sx, sy, sw, sh] = L.safeArea;
    for (const p of plots) {
      expect(p.x - R).toBeGreaterThanOrEqual(sx);
      expect(p.x + R).toBeLessThanOrEqual(sx + sw);
      expect(p.y - 180).toBeGreaterThanOrEqual(sy); // beacon T3 reaches ~180 px above the plot centre
      expect(p.y + RY).toBeLessThanOrEqual(sy + sh);
    }
  });

  it('no plot ring touches the road; every plot is within reach of every tower', () => {
    const pts = samples(4);
    // Shooting towers' and the barracks' (rally radius) T1 range; the Beacon's aura is not about the road.
    const reach = Math.min(...TOWER_TYPES.filter((t) => TOWER_DEFS[t].role !== 'support').map((t) => getTowerTierStats(t, 1).range)) * PPU;
    expect(reach).toBeGreaterThan(140);
    for (const [i, p] of plots.entries()) {
      // The drawn road is a spline through the same vertices (<= ~14 px off the polyline): keep
      // the ring ellipse + road half-width clear of the polyline with that slack.
      const ax = R + ROAD_HALF - 14;
      const ay = RY + ROAD_HALF - 14;
      for (const [qx, qy] of pts) expect(((qx - p.x) / ax) ** 2 + ((qy - p.y) / ay) ** 2, `plot ${i}`).toBeGreaterThanOrEqual(1);
      expect(roadDist(p.x, p.y), `plot ${i}`).toBeLessThanOrEqual(Math.min(135, reach));
    }
  });

  it('plots do not overlap each other and are spread out', () => {
    let minGap = Infinity;
    for (let i = 0; i < plots.length; i++) {
      for (let j = i + 1; j < plots.length; j++) {
        const dx = Math.abs(plots[i].x - plots[j].x);
        const dy = Math.abs(plots[i].y - plots[j].y);
        expect((dx / (2 * R + 14)) ** 2 + (dy / (2 * RY + 12)) ** 2, `plots ${i}/${j}`).toBeGreaterThanOrEqual(1);
        if (dx < 1.6 * R) expect(dy, `plot ${j} buried behind ${i}`).toBeGreaterThanOrEqual(100);
        minGap = Math.min(minGap, Math.hypot(dx, dy));
      }
    }
    expect(minGap).toBeGreaterThan(110);
  });

  it('keeps plots clear of the gates and the castle', () => {
    const roadW = 0.068 * IH;
    for (const e of L.entrances) for (const p of plots) expect(Math.hypot(p.x - e.x, p.y - e.y)).toBeGreaterThan(roadW * 1.8);
    const [gx, gy] = L.goal;
    for (const p of plots) expect(Math.abs(p.x - (gx + roadW * 0.4)) > 145 + R || p.y - RY > gy + roadW * 0.9 || p.y < gy - roadW * 2.1).toBe(true);
  });

  it('covers the whole route: both entrances, the merge, the last stretch', () => {
    const near = (pt: number[], r: number): number => plots.filter((p) => Math.hypot(p.x - pt[0], p.y - pt[1]) <= r).length;
    const [a, b] = L.paths;
    expect(near(a[2], 260)).toBeGreaterThanOrEqual(2); // first stretch from entrance A
    expect(near(b[2], 260)).toBeGreaterThanOrEqual(2); // first stretch from entrance B
    const merge = a.find((q) => b.some((r) => r[0] === q[0] && r[1] === q[1]))!;
    expect(near(merge, 230)).toBeGreaterThanOrEqual(2);
    expect(near(L.goal, 300)).toBeGreaterThanOrEqual(2);
    // Every 300 px stretch of road has a plot within 200 px (except the gate approach inside the castle art).
    for (const [x, y] of samples(300)) {
      if (Math.hypot(x - L.goal[0], y - L.goal[1]) < 200) continue;
      expect(near([x, y], 200), `road at ${Math.round(x)},${Math.round(y)}`).toBeGreaterThan(0);
    }
    expect(IW).toBeGreaterThan(0);
  });
});
